import os
import mysql.connector
from mysql.connector import Error

def connect_to_database():
    try:
        connection = mysql.connector.connect(
            host='localhost',
            database='image_db',
            user='your_username',
            password='your_password'
        )
        if connection.is_connected():
            print("MySQL データベースに接続されました")
            return connection
    except Error as e:
        print(f"データベース接続エラー: {e}")
        return None

def save_image_to_database(image_path, connection):
    try:
        with open(image_path, 'rb') as file:
            binary_data = file.read()

        cursor = connection.cursor()
        query = "INSERT INTO images (filename, image_data, upload_date) VALUES (%s, %s, NOW())"
        cursor.execute(query, (os.path.basename(image_path), binary_data))
        connection.commit()
        print(f"画像 '{os.path.basename(image_path)}' がデータベースに保存されました")
    except Error as e:
        print(f"画像の保存エラー: {e}")
    finally:
        if cursor:
            cursor.close()

def main():
    image_path = input("画像ファイルのパスを入力してください: ").strip()

    if not os.path.exists(image_path):
        print("指定されたファイルが存在しません。")
        return

    connection = connect_to_database()
    if connection:
        save_image_to_database(image_path, connection)
        connection.close()
        print("データベース接続を閉じました")
    else:
        print("データベースへの接続に失敗しました")

if __name__ == "__main__":
    main()
